public sealed record BaselineQuestionDefinition(string Key,IReadOnlyList<string> CanonicalSkillNames,string Prompt,IReadOnlyList<string> Options,string Answer,string Explanation)
{
    public string QuestionVersion => $"{AcceleratorBaselineQuestionCatalog.Version}-{Key}";
    public AcceleratorQuestion Create(Guid taxonomyId,Guid competencyId) => new() { TaxonomyId=taxonomyId,CompetencyId=competencyId,Version=QuestionVersion,
        Type=AcceleratorQuestionType.MultipleChoice,Difficulty=1,Weight=1,IsActive=true,Prompt=Prompt,OptionsJson=JsonSerializer.Serialize(OrderedOptions()),
        AnswerKeyJson=JsonSerializer.Serialize(new { answer=Answer }),RubricJson="{}",Explanation=Explanation };
    private IEnumerable<string> OrderedOptions()
    {
        // Stable option rotation avoids teaching candidates that the first option is always correct.
        var offset=System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(Key))[0]%Options.Count;
        return Options.Skip(offset).Concat(Options.Take(offset));
    }
}
